// A single logical WhatsApp reminder can be generated by both the daily
// scheduler and the older event-reminder workflow. Use the SAME durable key
// for a given recipient, template and event date/time, irrespective of which
// producer runs, whether it runs again, or whether quiet-hours postponed it.
// This key is NOT a receipt and is never used as proof of recipient delivery.
export function eventReminderWhatsAppKey(event:any,template:any,recipientKind:'supplier'|'admin',recipientId:any):string{
  const type=String(template?.type||'');
  if(!['SUPPLIER_EVENT_REMINDER','ADMIN_EVENT_REMINDER'].includes(type)||
     !['supplier','admin'].includes(recipientKind))throw new Error('Unsupported event reminder key');
  const eventId=String(event?.id||'').trim();
  const date=String(event?.event_date||'').slice(0,10);
  const time=String(event?.event_time||'').trim();
  const target=String(recipientId||'').trim();
  if(!eventId||!date||!target)throw new Error('Incomplete event reminder key');
  const timingValue=String(template?.timing_value??1);
  const timingUnit=String(template?.timing_unit||'days');
  const key=['event-reminder',type,eventId,date,time,timingValue,timingUnit,recipientKind,target].join(':');
  if(key.length>240)throw new Error('Event reminder key too long');
  return key;
}
